#!/usr/bin/env node
/**
 * Team Projects — Gateway RPC Handlers
 *
 * These handlers are registered as gateway RPC methods that the
 * Control UI calls to manage projects, tasks, and team chat.
 *
 * Since OpenClaw doesn't have a native plugin RPC system yet,
 * these are called via the agent as tool calls — the agent
 * reads project state and responds to UI requests.
 *
 * For now, this serves as a reference for what RPC methods
 * would be needed if/when gateway plugin RPC is added.
 *
 * In practice, the coordinator agent uses the project-store.js
 * CLI directly, and the UI communicates via chat messages.
 */

/**
 * RPC Method Specification
 *
 * These would be registered as gateway methods:
 *
 * projects.list          → listProjects({ status?, agentId? })
 * projects.create        → createProject({ name, description, coordinator, agents })
 * projects.get           → getProject({ id })
 * projects.update        → updateProject({ id, ...fields })
 * projects.delete        → deleteProject({ id })
 *
 * projects.phases.add    → addPhase({ projectId, name, description, order })
 * projects.phases.update → updatePhase({ projectId, phaseId, ...fields })
 * projects.phases.delete → deletePhase({ projectId, phaseId })
 *
 * projects.tasks.add     → addTask({ projectId, phaseId, title, description, assignee, priority })
 * projects.tasks.update  → updateTask({ projectId, taskId, ...fields })
 * projects.tasks.get     → getTask({ projectId, taskId })
 * projects.tasks.list    → listTasks({ projectId, assignee?, status?, phaseId? })
 * projects.tasks.delete  → deleteTask({ projectId, taskId })
 *
 * projects.comments.add  → addComment({ projectId, taskId, author, text })
 *
 * projects.chat.send     → appendChatMessage({ projectId, author, text, mentions })
 * projects.chat.history  → getChatHistory({ projectId, limit?, before? })
 *
 * projects.stats         → getProjectStats({ projectId })
 * projects.wbs           → getWBS({ projectId })
 *
 * projects.dispatch.plan → getDispatchPlan({ projectId })
 * projects.dispatch.ready → findReadyTasks({ projectId })
 * projects.dispatch.advance → advancePhases({ projectId })
 */

// ── Adapter: HTTP API (optional future enhancement) ─────────────────────

import http from "node:http";
import {
  createProject, listProjects, getProject, updateProject, deleteProject,
  addPhase, updatePhase, deletePhase,
  addTask, updateTask, getTask, listTasks, deleteTask,
  addComment,
  appendChatMessage, getChatHistory,
  getProjectStats, getWBS,
} from "./project-store.js";

import {
  findReadyTasks, getDispatchPlan, advancePhases,
} from "./orchestrator.js";

const PORT = parseInt(process.env.TEAM_PROJECTS_PORT || "0", 10);

if (PORT > 0) {
  const routes = {
    "POST /api/projects":        (body) => createProject(body),
    "GET /api/projects":         (body) => listProjects(body),
    "GET /api/projects/:id":     (body) => getProject(body.id),
    "PATCH /api/projects/:id":   (body) => updateProject(body.id, body),
    "DELETE /api/projects/:id":  (body) => deleteProject(body.id),
    "POST /api/phases":          (body) => addPhase(body.projectId, body),
    "POST /api/tasks":           (body) => addTask(body.projectId, body.phaseId, body),
    "PATCH /api/tasks/:id":      (body) => updateTask(body.projectId, body.id, body),
    "GET /api/tasks":            (body) => listTasks(body.projectId, body),
    "POST /api/comments":        (body) => addComment(body.projectId, body.taskId, body),
    "POST /api/chat":            (body) => appendChatMessage(body.projectId, body),
    "GET /api/chat":             (body) => getChatHistory(body.projectId, body),
    "GET /api/stats":            (body) => getProjectStats(body.projectId),
    "GET /api/wbs":              (body) => getWBS(body.projectId),
    "GET /api/dispatch/plan":    (body) => getDispatchPlan(body.projectId),
    "GET /api/dispatch/ready":   (body) => findReadyTasks(body.projectId),
    "POST /api/dispatch/advance": (body) => advancePhases(body.projectId),
  };

  const server = http.createServer(async (req, res) => {
    res.setHeader("Content-Type", "application/json");
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PATCH, DELETE, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");

    if (req.method === "OPTIONS") {
      res.writeHead(200);
      res.end();
      return;
    }

    try {
      let body = {};
      if (req.method !== "GET") {
        const chunks = [];
        for await (const chunk of req) chunks.push(chunk);
        const raw = Buffer.concat(chunks).toString("utf-8");
        if (raw) body = JSON.parse(raw);
      }

      // Parse URL params
      const url = new URL(req.url, `http://localhost:${PORT}`);
      for (const [k, v] of url.searchParams) body[k] = v;

      // Match route
      const routeKey = `${req.method} ${url.pathname}`;
      const handler = routes[routeKey];

      if (handler) {
        const result = await handler(body);
        res.writeHead(200);
        res.end(JSON.stringify({ ok: true, data: result }));
      } else {
        res.writeHead(404);
        res.end(JSON.stringify({ ok: false, error: "Not found" }));
      }
    } catch (err) {
      res.writeHead(500);
      res.end(JSON.stringify({ ok: false, error: err.message }));
    }
  });

  server.listen(PORT, "127.0.0.1", () => {
    console.log(`Team Projects API listening on http://127.0.0.1:${PORT}`);
  });
}

#!/usr/bin/env node
/**
 * Team Projects — Orchestrator
 *
 * The coordinator agent logic that:
 * 1. Reads the project plan
 * 2. Identifies next actionable tasks
 * 3. Dispatches them to appropriate agents via sessions_spawn
 * 4. Tracks completions and advances the project
 *
 * This is designed to be called as a tool by the coordinator agent,
 * or triggered via cron for autonomous project advancement.
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import path from "node:path";

const DATA_DIR = process.env.TEAM_PROJECTS_DIR ||
  path.join(process.env.HOME || "/root", ".openclaw", "workspace", "team-projects");
const DB_PATH = path.join(DATA_DIR, "projects.json");
const STATE_PATH = path.join(DATA_DIR, "orchestrator-state.json");

// ── State Management ────────────────────────────────────────────────────

function loadState() {
  if (!existsSync(STATE_PATH)) return { dispatched: {}, completions: [] };
  try {
    return JSON.parse(readFileSync(STATE_PATH, "utf-8"));
  } catch {
    return { dispatched: {}, completions: [] };
  }
}

function saveState(state) {
  if (!existsSync(DATA_DIR)) mkdirSync(DATA_DIR, { recursive: true });
  writeFileSync(STATE_PATH, JSON.stringify(state, null, 2), "utf-8");
}

function loadDB() {
  if (!existsSync(DB_PATH)) return { projects: [] };
  try {
    return JSON.parse(readFileSync(DB_PATH, "utf-8"));
  } catch {
    return { projects: [] };
  }
}

// ── Task Readiness Analysis ─────────────────────────────────────────────

/**
 * Determine which tasks are ready to be dispatched.
 * A task is ready when:
 * - status is "todo"
 * - all dependencies are "done"
 * - it has an assignee
 * - it hasn't already been dispatched (in current cycle)
 */
export function findReadyTasks(projectId) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return [];

  const state = loadState();

  // Build a set of completed task IDs
  const completedIds = new Set();
  for (const phase of (project.phases || [])) {
    for (const task of (phase.tasks || [])) {
      if (task.status === "done") completedIds.add(task.id);
    }
  }

  const ready = [];
  for (const phase of (project.phases || [])) {
    if (phase.status === "completed") continue;
    for (const task of (phase.tasks || [])) {
      if (task.status !== "todo") continue;
      if (!task.assignee) continue;

      // Check if already dispatched
      if (state.dispatched[task.id]) continue;

      // Check dependencies
      const deps = Array.isArray(task.dependsOn) ? task.dependsOn : (task.dependsOn ? [task.dependsOn] : []);
      const depsReady = deps.every(dep => completedIds.has(dep));
      if (!depsReady) continue;

      ready.push({
        taskId: task.id,
        title: task.title,
        description: task.description,
        assignee: task.assignee,
        priority: task.priority,
        phaseId: phase.id,
        phaseName: phase.name,
        dependsOn: task.dependsOn,
      });
    }
  }

  // Sort by priority: critical > high > medium > low
  const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
  ready.sort((a, b) => (priorityOrder[a.priority] || 99) - (priorityOrder[b.priority] || 99));

  return ready;
}

/**
 * Mark a task as dispatched (prevents double-dispatch).
 */
export function markDispatched(taskId, { sessionKey, agentId }) {
  const state = loadState();
  state.dispatched[taskId] = {
    sessionKey,
    agentId,
    dispatchedAt: new Date().toISOString(),
  };
  saveState(state);
}

/**
 * Record a task completion event.
 */
export function recordCompletion(taskId, { agentId, summary, artifacts }) {
  const state = loadState();
  delete state.dispatched[taskId];
  state.completions.push({
    taskId,
    agentId,
    summary,
    artifacts: artifacts || [],
    completedAt: new Date().toISOString(),
  });
  saveState(state);
}

/**
 * Get a dispatch plan for the coordinator agent.
 * Returns a structured plan that the agent can execute via sessions_spawn.
 */
export function getDispatchPlan(projectId) {
  const readyTasks = findReadyTasks(projectId);
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);

  if (!project) return { error: "Project not found" };

  // Group by assignee
  const byAgent = {};
  for (const task of readyTasks) {
    if (!byAgent[task.assignee]) byAgent[task.assignee] = [];
    byAgent[task.assignee].push(task);
  }

  // Build dispatch instructions
  const dispatches = [];
  for (const [agentId, tasks] of Object.entries(byAgent)) {
    for (const task of tasks) {
      dispatches.push({
        action: "sessions_spawn",
        agentId,
        task: buildTaskPrompt(task, project),
        taskId: task.id,
        priority: task.priority,
      });
    }
  }

  // Project progress
  let totalTasks = 0, doneTasks = 0;
  for (const phase of (project.phases || [])) {
    for (const task of (phase.tasks || [])) {
      totalTasks++;
      if (task.status === "done") doneTasks++;
    }
  }

  return {
    projectId: project.id,
    projectName: project.name,
    progress: totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0,
    totalTasks,
    completedTasks: doneTasks,
    readyToDispatch: dispatches.length,
    dispatches,
    blockedTasks: countBlockedTasks(project),
  };
}

function buildTaskPrompt(task, project) {
  let prompt = `# Task: ${task.title}\n\n`;
  prompt += `**Project:** ${project.name}\n`;
  prompt += `**Phase:** ${task.phaseName}\n`;
  prompt += `**Priority:** ${task.priority}\n`;
  prompt += `**Task ID:** ${task.taskId}\n\n`;
  if (task.description) prompt += `## Description\n\n${task.description}\n\n`;
  prompt += `## Instructions\n\n`;
  prompt += `Complete this task thoroughly. When finished:\n`;
  prompt += `1. Summarize what you did\n`;
  prompt += `2. List any artifacts (files created, URLs, etc.)\n`;
  prompt += `3. Note any issues or follow-up needed\n`;
  return prompt;
}

function countBlockedTasks(project) {
  const completedIds = new Set();
  let blocked = 0;
  for (const phase of (project.phases || [])) {
    for (const task of (phase.tasks || [])) {
      if (task.status === "done") completedIds.add(task.id);
    }
  }
  for (const phase of (project.phases || [])) {
    for (const task of (phase.tasks || [])) {
      if (task.status !== "todo") continue;
      const deps = Array.isArray(task.dependsOn) ? task.dependsOn : (task.dependsOn ? [task.dependsOn] : []);
      if (deps.length > 0 && !deps.every(d => completedIds.has(d))) {
        blocked++;
      }
    }
  }
  return blocked;
}

/**
 * Check if a project's current phase is complete and advance to next.
 */
export function advancePhases(projectId) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;

  const advanced = [];
  for (const phase of (project.phases || [])) {
    if (phase.status === "completed") continue;
    const tasks = phase.tasks || [];
    if (tasks.length === 0) continue;
    const allDone = tasks.every(t => t.status === "done");
    if (allDone) {
      phase.status = "completed";
      advanced.push(phase.id);
    } else if (tasks.some(t => t.status === "in_progress" || t.status === "review")) {
      if (phase.status !== "active") phase.status = "active";
    }
  }

  // Check if all phases are complete
  const allPhasesComplete = (project.phases || []).every(p => p.status === "completed");
  if (allPhasesComplete && project.status === "active") {
    project.status = "completed";
  }

  if (advanced.length > 0 || allPhasesComplete) {
    project.updatedAt = new Date().toISOString();
    const dbFull = loadDB();
    const idx = dbFull.projects.findIndex(p => p.id === project.id);
    if (idx !== -1) dbFull.projects[idx] = project;
    writeFileSync(DB_PATH, JSON.stringify(dbFull, null, 2), "utf-8");
  }

  return {
    advancedPhases: advanced,
    projectComplete: allPhasesComplete,
  };
}

// ── CLI Entry Point ─────────────────────────────────────────────────────

const [,, command, ...args] = process.argv;

if (command) {
  const projectId = args[0] || process.env.PROJECT_ID;
  let result;
  switch (command) {
    case "ready":
      result = findReadyTasks(projectId);
      break;
    case "plan":
      result = getDispatchPlan(projectId);
      break;
    case "advance":
      result = advancePhases(projectId);
      break;
    case "dispatched":
      result = loadState().dispatched;
      break;
    default:
      console.error(`Unknown command: ${command}`);
      process.exit(1);
  }
  console.log(JSON.stringify(result, null, 2));
}

#!/usr/bin/env node
/**
 * Team Projects — Project Store
 *
 * JSON-file-backed CRUD for projects, phases, tasks, and comments.
 * Designed to be called from Gateway RPC handlers or CLI.
 *
 * Storage: ~/.openclaw/workspace/team-projects/projects.json
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, appendFileSync } from "node:fs";
import { randomUUID } from "node:crypto";
import path from "node:path";

const DATA_DIR = process.env.TEAM_PROJECTS_DIR ||
  path.join(process.env.HOME || "/root", ".openclaw", "workspace", "team-projects");
const DB_PATH = path.join(DATA_DIR, "projects.json");

// ── Helpers ─────────────────────────────────────────────────────────────

function ensureDir() {
  if (!existsSync(DATA_DIR)) mkdirSync(DATA_DIR, { recursive: true });
}

function loadDB() {
  ensureDir();
  if (!existsSync(DB_PATH)) return { projects: [], version: 1 };
  try {
    return JSON.parse(readFileSync(DB_PATH, "utf-8"));
  } catch {
    return { projects: [], version: 1 };
  }
}

function saveDB(db) {
  ensureDir();
  writeFileSync(DB_PATH, JSON.stringify(db, null, 2), "utf-8");
}

function now() {
  return new Date().toISOString();
}

function slug(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 48);
}

// ── Project CRUD ────────────────────────────────────────────────────────

export function createProject({ name, description, coordinator, agents }) {
  const db = loadDB();
  const project = {
    id: `proj_${randomUUID().slice(0, 8)}`,
    slug: slug(name),
    name,
    description: description || "",
    coordinator: coordinator || "main",
    agents: agents || [],
    status: "planning",  // planning | active | paused | completed | archived
    phases: [],
    createdAt: now(),
    updatedAt: now(),
  };
  db.projects.push(project);
  saveDB(db);
  return project;
}

export function listProjects({ status, agentId } = {}) {
  const db = loadDB();
  let projects = db.projects;
  if (status) projects = projects.filter(p => p.status === status);
  if (agentId) projects = projects.filter(p =>
    p.coordinator === agentId ||
    p.agents.includes(agentId) ||
    p.phases?.some(ph => ph.tasks?.some(t => t.assignee === agentId))
  );
  return projects.map(p => ({
    ...p,
    taskCount: (p.phases || []).reduce((sum, ph) => sum + (ph.tasks || []).length, 0),
    completedCount: (p.phases || []).reduce((sum, ph) =>
      sum + (ph.tasks || []).filter(t => t.status === "done").length, 0),
  }));
}

export function getProject(projectId) {
  const db = loadDB();
  return db.projects.find(p => p.id === projectId || p.slug === projectId) || null;
}

export function updateProject(projectId, updates) {
  const db = loadDB();
  const idx = db.projects.findIndex(p => p.id === projectId || p.slug === projectId);
  if (idx === -1) return null;
  const allowed = ["name", "description", "status", "coordinator", "agents"];
  for (const key of allowed) {
    if (updates[key] !== undefined) db.projects[idx][key] = updates[key];
  }
  db.projects[idx].updatedAt = now();
  saveDB(db);
  return db.projects[idx];
}

export function deleteProject(projectId) {
  const db = loadDB();
  const idx = db.projects.findIndex(p => p.id === projectId || p.slug === projectId);
  if (idx === -1) return false;
  db.projects.splice(idx, 1);
  saveDB(db);
  return true;
}

// ── Phase CRUD ──────────────────────────────────────────────────────────

export function addPhase(projectId, { name, description, order }) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;
  if (!project.phases) project.phases = [];
  const phase = {
    id: `phase_${randomUUID().slice(0, 8)}`,
    name,
    description: description || "",
    order: order ?? project.phases.length,
    status: "pending",  // pending | active | completed
    tasks: [],
    createdAt: now(),
  };
  project.phases.push(phase);
  project.phases.sort((a, b) => a.order - b.order);
  project.updatedAt = now();
  saveDB(db);
  return phase;
}

export function updatePhase(projectId, phaseId, updates) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;
  const phase = (project.phases || []).find(ph => ph.id === phaseId);
  if (!phase) return null;
  const allowed = ["name", "description", "status", "order"];
  for (const key of allowed) {
    if (updates[key] !== undefined) phase[key] = updates[key];
  }
  project.updatedAt = now();
  saveDB(db);
  return phase;
}

export function deletePhase(projectId, phaseId) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return false;
  const idx = (project.phases || []).findIndex(ph => ph.id === phaseId);
  if (idx === -1) return false;
  project.phases.splice(idx, 1);
  project.updatedAt = now();
  saveDB(db);
  return true;
}

// ── Task CRUD ───────────────────────────────────────────────────────────

export function addTask(projectId, phaseId, { title, description, assignee, priority, tags, dependsOn }) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;
  const phase = (project.phases || []).find(ph => ph.id === phaseId);
  if (!phase) return null;
  if (!phase.tasks) phase.tasks = [];
  const task = {
    id: `task_${randomUUID().slice(0, 8)}`,
    title,
    description: description || "",
    assignee: assignee || null,
    priority: priority || "medium",  // critical | high | medium | low
    status: "todo",  // todo | in_progress | blocked | review | done
    tags: tags || [],
    dependsOn: Array.isArray(dependsOn) ? dependsOn : (dependsOn ? [dependsOn] : []),
    sessionKey: null,     // filled when agent picks up the task
    comments: [],
    artifacts: [],        // file paths, URLs, etc.
    createdAt: now(),
    updatedAt: now(),
    startedAt: null,
    completedAt: null,
  };
  phase.tasks.push(task);
  project.updatedAt = now();
  saveDB(db);
  return task;
}

export function updateTask(projectId, taskId, updates) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;
  for (const phase of (project.phases || [])) {
    const task = (phase.tasks || []).find(t => t.id === taskId);
    if (!task) continue;
    const allowed = [
      "title", "description", "assignee", "priority", "status",
      "tags", "dependsOn", "sessionKey", "artifacts",
    ];
    for (const key of allowed) {
      if (updates[key] !== undefined) task[key] = updates[key];
    }
    if (updates.status === "in_progress" && !task.startedAt) {
      task.startedAt = now();
    }
    if (updates.status === "done" && !task.completedAt) {
      task.completedAt = now();
    }
    task.updatedAt = now();
    project.updatedAt = now();
    saveDB(db);
    return task;
  }
  return null;
}

export function getTask(projectId, taskId) {
  const project = getProject(projectId);
  if (!project) return null;
  for (const phase of (project.phases || [])) {
    const task = (phase.tasks || []).find(t => t.id === taskId);
    if (task) return { ...task, phaseId: phase.id, phaseName: phase.name };
  }
  return null;
}

export function listTasks(projectId, { assignee, status, phaseId, priority } = {}) {
  const project = getProject(projectId);
  if (!project) return [];
  const tasks = [];
  for (const phase of (project.phases || [])) {
    if (phaseId && phase.id !== phaseId) continue;
    for (const task of (phase.tasks || [])) {
      if (assignee && task.assignee !== assignee) continue;
      if (status && task.status !== status) continue;
      if (priority && task.priority !== priority) continue;
      tasks.push({ ...task, phaseId: phase.id, phaseName: phase.name });
    }
  }
  return tasks;
}

export function deleteTask(projectId, taskId) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return false;
  for (const phase of (project.phases || [])) {
    const idx = (phase.tasks || []).findIndex(t => t.id === taskId);
    if (idx === -1) continue;
    phase.tasks.splice(idx, 1);
    project.updatedAt = now();
    saveDB(db);
    return true;
  }
  return false;
}

// ── Task Comments ───────────────────────────────────────────────────────

export function addComment(projectId, taskId, { author, text }) {
  const db = loadDB();
  const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
  if (!project) return null;
  for (const phase of (project.phases || [])) {
    const task = (phase.tasks || []).find(t => t.id === taskId);
    if (!task) continue;
    if (!task.comments) task.comments = [];
    const comment = {
      id: `cmt_${randomUUID().slice(0, 8)}`,
      author,
      text,
      createdAt: now(),
    };
    task.comments.push(comment);
    task.updatedAt = now();
    project.updatedAt = now();
    saveDB(db);
    return comment;
  }
  return null;
}

// ── Team Chat Log ───────────────────────────────────────────────────────

export function appendChatMessage(projectId, { author, text, mentions, taskRef }) {
  const chatPath = path.join(DATA_DIR, `chat_${projectId}.jsonl`);
  ensureDir();
  const entry = {
    id: `msg_${randomUUID().slice(0, 8)}`,
    author,
    text,
    mentions: mentions || [],
    taskRef: taskRef || null,
    timestamp: now(),
  };
  const line = JSON.stringify(entry) + "\n";
  appendFileSync(chatPath, line, "utf-8");
  return entry;
}

export function getChatHistory(projectId, { limit, before } = {}) {
  const chatPath = path.join(DATA_DIR, `chat_${projectId}.jsonl`);
  if (!existsSync(chatPath)) return [];
  const lines = readFileSync(chatPath, "utf-8").trim().split("\n").filter(Boolean);
  let messages = lines.map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  if (before) messages = messages.filter(m => m.timestamp < before);
  if (limit) messages = messages.slice(-limit);
  return messages;
}

// ── Project Summary / Stats ─────────────────────────────────────────────

export function getProjectStats(projectId) {
  const project = getProject(projectId);
  if (!project) return null;
  const allTasks = [];
  for (const phase of (project.phases || [])) {
    for (const task of (phase.tasks || [])) {
      allTasks.push(task);
    }
  }
  const byStatus = {};
  const byAssignee = {};
  const byPriority = {};
  for (const t of allTasks) {
    byStatus[t.status] = (byStatus[t.status] || 0) + 1;
    if (t.assignee) byAssignee[t.assignee] = (byAssignee[t.assignee] || 0) + 1;
    byPriority[t.priority] = (byPriority[t.priority] || 0) + 1;
  }
  const total = allTasks.length;
  const done = byStatus.done || 0;
  return {
    projectId: project.id,
    name: project.name,
    status: project.status,
    phases: (project.phases || []).length,
    totalTasks: total,
    completedTasks: done,
    progress: total > 0 ? Math.round((done / total) * 100) : 0,
    byStatus,
    byAssignee,
    byPriority,
  };
}

// ── WBS (Work Breakdown Structure) ──────────────────────────────────────

export function getWBS(projectId) {
  const project = getProject(projectId);
  if (!project) return null;
  return {
    project: { id: project.id, name: project.name, status: project.status },
    phases: (project.phases || []).map(ph => ({
      id: ph.id,
      name: ph.name,
      status: ph.status,
      order: ph.order,
      tasks: (ph.tasks || []).map(t => ({
        id: t.id,
        title: t.title,
        assignee: t.assignee,
        status: t.status,
        priority: t.priority,
        dependsOn: t.dependsOn,
      })),
    })),
  };
}

// ── CLI Entry Point ─────────────────────────────────────────────────────

const [,, command, ...args] = process.argv;

function parseArgs(args) {
  const result = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith("--")) {
      const key = args[i].slice(2);
      const val = args[i + 1] && !args[i + 1].startsWith("--") ? args[++i] : true;
      // Handle arrays (comma-separated)
      if (typeof val === "string" && val.includes(",")) {
        result[key] = val.split(",").map(s => s.trim());
      } else {
        result[key] = val;
      }
    }
  }
  return result;
}

if (command) {
  const opts = parseArgs(args);
  let result;
  switch (command) {
    case "create-project":
      result = createProject(opts);
      break;
    case "list-projects":
      result = listProjects(opts);
      break;
    case "get-project":
      result = getProject(opts.id);
      break;
    case "update-project":
      result = updateProject(opts.id, opts);
      break;
    case "delete-project":
      result = deleteProject(opts.id);
      break;
    case "add-phase":
      result = addPhase(opts.project, opts);
      break;
    case "update-phase":
      result = updatePhase(opts.project, opts.id, opts);
      break;
    case "add-task":
      result = addTask(opts.project, opts.phase, opts);
      break;
    case "update-task":
      result = updateTask(opts.project, opts.id, opts);
      break;
    case "get-task":
      result = getTask(opts.project, opts.id);
      break;
    case "list-tasks":
      result = listTasks(opts.project, opts);
      break;
    case "add-comment":
      result = addComment(opts.project, opts.task, opts);
      break;
    case "stats":
      result = getProjectStats(opts.id || opts.project);
      break;
    case "wbs":
      result = getWBS(opts.id || opts.project);
      break;
    default:
      console.error(`Unknown command: ${command}`);
      process.exit(1);
  }
  console.log(JSON.stringify(result, null, 2));
}

#!/usr/bin/env node
/**
 * Team Projects — Task Router
 *
 * Parses @-mentions from team chat messages and dispatches tasks
 * to the appropriate agent via sessions_spawn or sessions_send.
 *
 * Called by the coordinator agent or gateway hook.
 */

import { readFileSync, existsSync } from "node:fs";
import path from "node:path";

const DATA_DIR = process.env.TEAM_PROJECTS_DIR ||
  path.join(process.env.HOME || "/root", ".openclaw", "workspace", "team-projects");

// ── @-Mention Parsing ───────────────────────────────────────────────────

/**
 * Extract @mentions from a message.
 * Supports: @agentId, @agent-id, @agent_id
 * Returns: [{ agentId, start, end }]
 */
export function parseMentions(text) {
  const mentions = [];
  const re = /@([a-zA-Z][a-zA-Z0-9_-]{0,63})\b/g;
  let match;
  while ((match = re.exec(text)) !== null) {
    mentions.push({
      agentId: match[1].toLowerCase(),
      raw: match[0],
      start: match.index,
      end: match.index + match[0].length,
    });
  }
  return mentions;
}

/**
 * Extract task references from a message.
 * Supports: #task_abc123, #phase_abc123
 */
export function parseTaskRefs(text) {
  const refs = [];
  const re = /#(task_[a-f0-9]+|phase_[a-f0-9]+)/g;
  let match;
  while ((match = re.exec(text)) !== null) {
    refs.push({ ref: match[1], start: match.index, end: match.index + match[0].length });
  }
  return refs;
}

/**
 * Build a dispatch plan from a message.
 * Returns which agents to notify and with what context.
 */
export function buildDispatchPlan(message, { projectId, author, availableAgents }) {
  const mentions = parseMentions(message);
  const taskRefs = parseTaskRefs(message);

  // Deduplicate mentioned agents
  const mentionedAgents = [...new Set(mentions.map(m => m.agentId))];

  // Filter to only agents that exist
  const validAgents = mentionedAgents.filter(a =>
    availableAgents.includes(a) || a === "all" || a === "team"
  );

  // @all or @team means broadcast to all agents
  const isBroadcast = validAgents.includes("all") || validAgents.includes("team");
  const targetAgents = isBroadcast
    ? availableAgents.filter(a => a !== author)
    : validAgents.filter(a => a !== author);

  // Strip mentions from the message body for clean forwarding
  let cleanMessage = message;
  for (const m of mentions) {
    cleanMessage = cleanMessage.replace(m.raw, "").trim();
  }

  return {
    original: message,
    cleanMessage,
    author,
    projectId,
    mentions,
    taskRefs,
    targetAgents,
    isBroadcast,
    dispatchType: targetAgents.length === 0
      ? "no_target"
      : targetAgents.length === 1
        ? "direct"
        : "multi",
  };
}

/**
 * Build the system prompt context for a dispatched message.
 * Gives the receiving agent context about the project and their role.
 */
export function buildAgentContext({ projectId, taskId, agentId, allAgents }) {
  let ctx = `## Team Project Context\n`;
  ctx += `You are agent "${agentId}" working on project "${projectId}".\n`;
  ctx += `Available team members: ${allAgents.join(", ")}\n`;
  ctx += `To communicate with other agents, use @agentId in your response.\n`;
  ctx += `To reference tasks, use #taskId.\n`;

  if (taskId) {
    // Load task details
    try {
      const dbPath = path.join(DATA_DIR, "projects.json");
      if (existsSync(dbPath)) {
        const db = JSON.parse(readFileSync(dbPath, "utf-8"));
        const project = db.projects.find(p => p.id === projectId || p.slug === projectId);
        if (project) {
          for (const phase of (project.phases || [])) {
            const task = (phase.tasks || []).find(t => t.id === taskId);
            if (task) {
              ctx += `\n### Current Task: ${task.title}\n`;
              ctx += `- **ID:** ${task.id}\n`;
              ctx += `- **Phase:** ${phase.name}\n`;
              ctx += `- **Priority:** ${task.priority}\n`;
              ctx += `- **Status:** ${task.status}\n`;
              if (task.description) ctx += `- **Description:** ${task.description}\n`;
              if (task.dependsOn?.length) ctx += `- **Depends on:** ${task.dependsOn.join(", ")}\n`;
              break;
            }
          }
        }
      }
    } catch { /* ignore read errors */ }
  }

  return ctx;
}

/**
 * Format a task assignment message for an agent.
 */
export function formatTaskAssignment({ task, phase, project, fromAgent }) {
  let msg = `📋 **Task Assignment from @${fromAgent}**\n\n`;
  msg += `**Project:** ${project.name}\n`;
  msg += `**Phase:** ${phase.name}\n`;
  msg += `**Task:** ${task.title} (#${task.id})\n`;
  msg += `**Priority:** ${task.priority}\n`;
  if (task.description) msg += `\n${task.description}\n`;
  if (task.dependsOn?.length) {
    msg += `\n**Dependencies:** ${task.dependsOn.map(d => `#${d}`).join(", ")}\n`;
  }
  msg += `\nWhen you complete this task, update its status by including in your response:\n`;
  msg += `\`TASK_COMPLETE: #${task.id}\`\n`;
  msg += `\nIf you need help from another agent, tag them: \`@agentId your request\`\n`;
  return msg;
}

// ── CLI Entry Point ─────────────────────────────────────────────────────

const [,, command, ...args] = process.argv;

if (command === "parse") {
  const text = args.join(" ");
  const mentions = parseMentions(text);
  const taskRefs = parseTaskRefs(text);
  console.log(JSON.stringify({ mentions, taskRefs }, null, 2));
}

if (command === "plan") {
  const text = args.join(" ");
  const plan = buildDispatchPlan(text, {
    projectId: process.env.PROJECT_ID || "unknown",
    author: process.env.AUTHOR || "main",
    availableAgents: (process.env.AGENTS || "main").split(","),
  });
  console.log(JSON.stringify(plan, null, 2));
}

